{"cards": [{"node_code": "N_036cdbe25fdbee72", "definition": "研究汽车动力源的工作原理、结构组成、性能参数及设计制造技术的领域，涵盖内燃机、燃气轮机及其他新型动力装置。", "boundary": "本节点聚焦于汽车“动力源”本身的技术。边界在于区分“发动机”与“整车”（整车侧重系统集成，归整车设计）、“发动机”与“底盘”（底盘侧重传动与行驶，归结构部件）。若内容涉及发动机控制策略，归本节点；若涉及发动机在整车中的布置与匹配，视具体语境可关联整车设计。", "includes": ["往复式内燃机（汽油、柴油）的结构、原理与制造", "旋转活塞式发动机、燃气轮机的技术特性", "发动机性能试验、排放控制及新型动力装置研发"], "excludes": ["汽车底盘传动系统（变速箱、驱动桥）", "整车总体设计与匹配"], "sibling_distinctions": [{"other_code": "N_92c8504d615665c9", "rule": "汽车发动机侧重动力产生，汽车结构部件侧重底盘、车身等承载与传动部件。"}, {"other_code": "N_3a8ee85426a63c7a", "rule": "汽车发动机是单一总成技术，整车设计侧重各总成的集成、匹配与总体性能。"}], "cross_boundary_rule": "若内容涉及“发动机与变速箱的匹配”，主挂载汽车发动机（侧重动力特性）；若涉及“整车动力性计算”，主挂载整车设计与计算。"}, {"node_code": "N_92874447954d8507", "definition": "研究汽车制造中使用的各类材料（金属、非金属、复合材料）的性能、选用原则、加工工艺及失效分析的技术领域。", "boundary": "本节点聚焦于汽车“材料”科学。边界在于区分“材料”与“制造工艺”（工艺侧重加工方法，归制造工艺）、“材料”与“结构设计”（设计侧重力学计算，归结构部件）。若内容涉及材料在特定零件中的应用，归本节点；若涉及材料成型工艺细节，归制造工艺。", "includes": ["黑色金属、有色金属及其合金在汽车中的应用", "高分子材料、复合材料及粉末冶金材料特性", "汽车材料的选择标准、热处理及腐蚀防护"], "excludes": ["材料的具体成型加工技术（如冲压、焊接工艺）", "零部件的结构设计与强度计算"], "sibling_distinctions": [{"other_code": "N_228cca3ba3beb193", "rule": "汽车材料侧重材料本身的属性与选用，汽车制造工艺侧重将材料加工成零件的方法与流程。"}, {"other_code": "N_92c8504d615665c9", "rule": "汽车材料是基础物质，汽车结构部件是应用材料形成的具体功能组件。"}], "cross_boundary_rule": "若内容涉及“材料热处理工艺”，主挂载汽车材料（侧重材料性能改变）；若涉及“零件冲压成型”，主挂载汽车制造工艺。"}, {"node_code": "N_228cca3ba3beb193", "definition": "研究汽车及其零部件从原材料到成品的加工方法、工艺流程、设备选用及质量控制的技术领域。", "boundary": "本节点聚焦于汽车“制造过程”。边界在于区分“制造工艺”与“材料”（材料侧重属性，归材料）、“制造工艺”与“设计”（设计侧重功能实现，归设计）。若内容涉及焊接、铸造、冲压、装配等具体工艺，归本节点；若涉及生产线布局与管理，归汽车制造厂。", "includes": ["汽车零件的铸造、锻造、冲压、焊接工艺", "发动机、底盘等总成的装配工艺与流程", "制造工艺设计、工装夹具设计及质量控制技术"], "excludes": ["汽车材料的基础物理化学性质研究", "汽车制造企业的生产管理、财务与市场营销"], "sibling_distinctions": [{"other_code": "N_92874447954d8507", "rule": "汽车制造工艺侧重“怎么做”（加工方法），汽车材料侧重“用什么”（物质属性）。"}, {"other_code": "N_7e3a8b56fcc56804", "rule": "汽车制造工艺侧重技术细节，汽车制造厂侧重企业组织、生产管理与工厂规划。"}], "cross_boundary_rule": "若内容涉及“工艺对材料性能的影响”，主挂载汽车制造工艺；若涉及“材料对工艺可行性的限制”，主挂载汽车材料。"}]}
